function startOfWeek(d){d=new Date(d);d.setHours(0,0,0,0);const day=d.getDay();d.setDate(d.getDate()-((day+6)%7));return d}
function dateKey(d){const x=new Date(d);const y=x.getFullYear(),m=String(x.getMonth()+1).padStart(2,'0'),day=String(x.getDate()).padStart(2,'0');return `${y}-${m}-${day}`} function addDays(d,n){const x=new Date(d);x.setDate(x.getDate()+n);return x}
function weekEnd(w){return addDays(w,6)}
function effectiveShiftDate(s){if(!s?.date)return'';if(s.dateVersion===2)return s.date;const legacyWeekly=String(s.notes||'').includes('Created in weekly roster');return legacyWeekly?dateKey(addDays(new Date(s.date+'T00:00:00'),1)):s.date}
function inWeek(dateOrShift,w){const key=typeof dateOrShift==='object'?effectiveShiftDate(dateOrShift):dateOrShift;const t=new Date(key+'T00:00:00');return t>=startOfWeek(w)&&t<=weekEnd(startOfWeek(w))}
function weekText(w){return `${addDays(w,0).toLocaleDateString('en-AU',{day:'numeric',month:'short'})} – ${weekEnd(w).toLocaleDateString('en-AU',{day:'numeric',month:'short',year:'numeric'})}`}
function hours(s){let [sh,sm]=s.start.split(':').map(Number),[eh,em]=s.end.split(':').map(Number);let mins=eh*60+em-(sh*60+sm);if(mins<0)mins+=1440;return Math.max(0,mins/60)}
function storeDetail(name){return STORE_DETAILS[name]||null}
function storeHoursFor(name,date){const detail=storeDetail(name);if(!detail||!date)return null;const jsDay=new Date(date+'T00:00:00').getDay();const mondayIndex=(jsDay+6)%7;return detail.hours[mondayIndex]}
function formatTime(t){const [h,m]=t.split(':').map(Number);return new Date(2000,0,1,h,m).toLocaleTimeString('en-AU',{hour:'numeric',minute:'2-digit'})}
function applyStoreHours(){const h=storeHoursFor($('shiftOutlet').value,$('shiftDate').value);if(!h)return;$('shiftStart').value=h[0];$('shiftEnd').value=h[1];$('shiftType').value='Full day';$('shiftBreak').value=0;updateStoreHoursHint()}
function updateStoreHoursHint(){const detail=storeDetail($('shiftOutlet').value),h=storeHoursFor($('shiftOutlet').value,$('shiftDate').value);if(!detail||!h){$('storeHoursHint').textContent='';return}$('storeHoursHint').textContent=`Store hours: ${formatTime(h[0])} – ${formatTime(h[1])} · ${detail.address}`}
function outsideStoreHours(row){const h=storeHoursFor(row.location,row.date);return !!h&&(row.start<h[0]||row.end>h[1])}
function accountKey(a){return `${String(a.invoiceNumber||'').trim().toUpperCase()}|${supplierKey(a.supplier)}|${Number(a.amount||0).toFixed(2)}`}function normalize(raw){const employees=(raw.employees||NAMES).map(e=>{const emp=typeof e==='string'?baseEmployee(e):{...baseEmployee(e.name),...e};return{...emp,satMultiplier:1,sunMultiplier:1}});const imported=IMPORTED_RECEIVING.map(a=>applySupplierPaymentDefaults({...a}));const saved=Array.isArray(raw.accounts)?raw.accounts:[];const byKey=new Map(imported.map(a=>[accountKey(a),a]));for(const s of saved){const k=accountKey(s),base=byKey.get(k)||{};const merged={...base,...s};if((!s.paymentStatus||['Unconfirmed','Unpaid'].includes(s.paymentStatus))&&base.paymentStatus==='Paid')merged.paymentStatus='Paid';if(!merged.receiptNumber)merged.receiptNumber=merged.paymentReference||'';byKey.set(k,applySupplierPaymentDefaults(merged))}const accounts=[...byKey.values()];return{employees,locations:raw.locations?.length?raw.locations:LOCATIONS,shifts:raw.shifts||[],accounts}}
function setStatus(ok,text){$('connectionStatus').className=`status ${ok?'online':'offline'}`;$('connectionStatus').textContent=text}
function toast(msg){$('toast').textContent=msg;$('toast').classList.remove('hidden');setTimeout(()=>$('toast').classList.add('hidden'),2500)}
async function load(){const {data,error}=await db.from('roster_state').select('*').eq('id',1).single();if(error)throw error;state=normalize(data.state||{});revision=Number(data.revision||0)}
async function save(){
  if(saving){queued=true;return true}
  saving=true;setStatus(true,'Saving…');
  let ok=false;
  try{
    // Remove undefined/browser-only values before sending the state to Postgres JSONB.
    const cleanState=JSON.parse(JSON.stringify(state));
    let {data:sessionData}=await db.auth.getSession();
    if(!sessionData?.session){
      const refreshed=await db.auth.refreshSession();
      if(refreshed.error||!refreshed.data?.session)throw new Error('Your login session expired. Please sign out and sign in again.');
    }
    let result=await db.rpc('save_roster_state',{p_state:cleanState,p_base_revision:revision,p_updated_by:currentUser?.email||'Admin'});
    // Retry once when the access token expired between loading and saving.
    if(result.error&&/jwt|token|auth/i.test(result.error.message||'')){
      const refreshed=await db.auth.refreshSession();
      if(!refreshed.error)result=await db.rpc('save_roster_state',{p_state:cleanState,p_base_revision:revision,p_updated_by:currentUser?.email||'Admin'});
    }
    if(result.error)throw result.error;
    const row=Array.isArray(result.data)?result.data[0]:result.data;
    if(row?.conflict){
      state=normalize(row.state||{});revision=Number(row.revision||0);
      setStatus(false,'Reloaded latest data');
      toast('Another user saved changes first. Latest cloud data was reloaded; please repeat your last edit.');
      render();
      return false;
    }
    revision=Number(row?.revision||revision+1);
    state=cleanState;
    setStatus(true,'Cloud synced');render();ok=true;
    return true;
  }catch(e){
    console.error('Supabase save failed',e);
    const message=e?.message||e?.details||'Unknown cloud error';
    setStatus(false,'Save failed');
    toast(`Save failed: ${message}`);
    return false;
  }finally{
    saving=false;
    if(queued){queued=false;setTimeout(()=>save(),100)}
  }
}
function subscribe(){if(channel)db.removeChannel(channel);channel=db.channel('supps247-admin').on('postgres_changes',{event:'UPDATE',schema:'public',table:'roster_state',filter:'id=eq.1'},p=>{if(Number(p.new.revision)>revision){revision=Number(p.new.revision);state=normalize(p.new.state||{});render();toast('Updated from another device')}}).subscribe()}
function employee(name){return state.employees.find(e=>e.name===name)||baseEmployee(name)}
function payrollRows(week,outlet='All outlets'){return state.employees.map(emp=>{let weekday=0,sat=0,sun=0;state.shifts.filter(s=>s.employee===emp.name&&inWeek(s,week)&&(outlet==='All outlets'||s.location===outlet)).forEach(s=>{const h=hours(s);const d=new Date(effectiveShiftDate(s)+'T00:00:00').getDay();if(d===6)sat+=h;else if(d===0)sun+=h;else weekday+=h});const gross=(weekday+sat+sun)*emp.baseRate;const allowance=(weekday+sat+sun)>0?Number(emp.weeklyAllowance||0):0;return{emp,weekday,sat,sun,gross,allowance,total:gross+allowance}}).filter(r=>r.weekday+r.sat+r.sun>0)}

function weeklyCellShift(employeeName,dayIndex,outlet){const date=dateKey(addDays(currentWeek,dayIndex));return state.shifts.find(s=>s.employee===employeeName&&s.location===outlet&&effectiveShiftDate(s)===date)||null}
function weeklyPresetFor(s){if(!s)return'Off';if(s.shiftType&&['Full day','Half AM','Half PM'].includes(s.shiftType))return s.shiftType;return'Custom'}
function weeklyCellHtml(emp,dayIndex,outlet){const s=weeklyCellShift(emp.name,dayIndex,outlet),preset=weeklyPresetFor(s),date=dateKey(addDays(currentWeek,dayIndex)),h=storeHoursFor(outlet,date)||['09:00','17:00'];let start=s?.start||h[0],end=s?.end||h[1];return `<td class="weekly-cell ${preset==='Off'?'weekly-off':''}" data-employee="${esc(emp.name)}" data-day="${dayIndex}"><select class="weekly-preset"><option${preset==='Off'?' selected':''}>Off</option><option${preset==='Full day'?' selected':''}>Full day</option><option${preset==='Half AM'?' selected':''}>Half AM</option><option${preset==='Half PM'?' selected':''}>Half PM</option><option${preset==='Custom'?' selected':''}>Custom</option></select><div class="weekly-time-row"><input class="weekly-start" type="time" value="${start}"><input class="weekly-end" type="time" value="${end}"></div><input class="weekly-break" type="hidden" value="0"><span class="weekly-hours">${preset==='Off'?'Off':formatTime(start)+'–'+formatTime(end)}</span></td>`}
function renderWeeklyRosterGrid(){const outlet=$('weeklyRosterOutlet').value||state.locations[0];$('weeklyRosterWeekLabel').textContent=weekText(currentWeek);$('weeklyRosterBody').innerHTML=state.employees.map(emp=>`<tr><td class="weekly-name">${esc(emp.name)}</td>${Array.from({length:7},(_,i)=>weeklyCellHtml(emp,i,outlet)).join('')}</tr>`).join('');document.querySelectorAll('.weekly-preset').forEach(el=>el.onchange=()=>applyWeeklyPreset(el.closest('.weekly-cell')));document.querySelectorAll('.weekly-start,.weekly-end').forEach(el=>el.onchange=()=>updateWeeklyCellLabel(el.closest('.weekly-cell')))}
function applyWeeklyPreset(cell){const preset=cell.querySelector('.weekly-preset').value,outlet=$('weeklyRosterOutlet').value,date=dateKey(addDays(currentWeek,Number(cell.dataset.day))),h=storeHoursFor(outlet,date)||['09:00','17:00'],start=cell.querySelector('.weekly-start'),end=cell.querySelector('.weekly-end'),br=cell.querySelector('.weekly-break');cell.classList.toggle('weekly-off',preset==='Off');if(preset==='Full day'){start.value=h[0];end.value=h[1];br.value=30}else if(preset==='Half AM'){start.value=h[0];const [oh,om]=h[0].split(':').map(Number);start.value=h[0];end.value=`${String(Math.min(23,oh+4)).padStart(2,'0')}:${String(om).padStart(2,'0')}`;br.value=0}else if(preset==='Half PM'){const [eh,em]=h[1].split(':').map(Number);start.value=`${String(Math.max(0,eh-4)).padStart(2,'0')}:${String(em).padStart(2,'0')}`;end.value=h[1];br.value=0}updateWeeklyCellLabel(cell)}
function updateWeeklyCellLabel(cell){const p=cell.querySelector('.weekly-preset').value,s=cell.querySelector('.weekly-start').value,e=cell.querySelector('.weekly-end').value;cell.querySelector('.weekly-hours').textContent=p==='Off'?'Off':`${formatTime(s)}–${formatTime(e)}`}
function openWeeklyRoster(){renderWeeklyRosterGrid();$('weeklyRosterDialog').showModal()}
function renderSelects(){const empOpts=state.employees.map(e=>`<option>${esc(e.name)}</option>`).join('');const locOpts=state.locations.map(x=>`<option>${esc(x)}</option>`).join('');$('shiftEmployee').innerHTML=empOpts;$('shiftOutlet').innerHTML=locOpts;$('weeklyRosterOutlet').innerHTML=locOpts;$('employeeOutlet').innerHTML=locOpts;$('rosterOutletFilter').innerHTML=`<option>All outlets</option>${locOpts}`;$('payrollOutletFilter').innerHTML=`<option>All outlets</option>${locOpts}`;$('rosterEmployeeFilter').innerHTML=`<option>All employees</option>${empOpts}`}
function esc(v){return String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
function render(){renderSelects();$('weekLabel').textContent=weekText(currentWeek);$('payWeekLabel').textContent=weekText(payWeek);renderRoster();renderEmployees();renderPayroll();renderDashboard();renderStores();renderAccounts();renderReports()}
function renderRoster(){const outlet=$('rosterOutletFilter').value||'All outlets',emp=$('rosterEmployeeFilter').value||'All employees';const rows=state.shifts.filter(s=>inWeek(s,currentWeek)&&(outlet==='All outlets'||s.location===outlet)&&(emp==='All employees'||s.employee===emp)).sort((a,b)=>a.date.localeCompare(b.date)||a.start.localeCompare(b.start));$('rosterBody').innerHTML=rows.length?rows.map(s=>`<tr><td>${new Date(effectiveShiftDate(s)+'T00:00:00').toLocaleDateString('en-AU',{weekday:'short',day:'numeric',month:'short'})}</td><td>${esc(s.employee)}</td><td>${esc(s.location)}</td><td>${s.start}–${s.end}${outsideStoreHours(s)?'<br><span class="warning-text">Outside store hours</span>':''}</td><td>${hours(s).toFixed(2)}</td><td>${s.publicHoliday?'Public holiday':esc(s.shiftType||'Custom')}</td><td><div class="actions"><button class="action-btn" onclick="editShift('${s.id}')">Edit</button><button class="action-btn delete" onclick="deleteShift('${s.id}')">Delete</button></div></td></tr>`).join(''):`<tr><td colspan="7" class="empty">No shifts for this week.</td></tr>`}
function renderEmployees(){$('employeesBody').innerHTML=state.employees.map(e=>`<tr><td><strong>${esc(e.name)}</strong></td><td>${esc(e.homeOutlet)}</td><td>${esc(e.employmentType)}</td><td>${money(e.baseRate)}</td><td>${e.satMultiplier}×</td><td>${e.sunMultiplier}×</td><td><div class="actions"><button class="action-btn" onclick="editEmployee('${encodeURIComponent(e.name)}')">Edit</button><button class="action-btn delete" onclick="deleteEmployee('${encodeURIComponent(e.name)}')">Delete</button></div></td></tr>`).join('')}
function renderPayroll(){const rows=payrollRows(payWeek,$('payrollOutletFilter').value||'All outlets');$('payrollBody').innerHTML=rows.length?rows.map(r=>`<tr><td><strong>${esc(r.emp.name)}</strong><br><small>${money(r.emp.baseRate)}/hr</small></td><td>${r.weekday.toFixed(2)}</td><td>${r.sat.toFixed(2)}</td><td>${r.sun.toFixed(2)}</td><td>${money(r.gross)}</td><td>${money(r.allowance)}</td><td><strong>${money(r.total)}</strong></td></tr>`).join(''):`<tr><td colspan="7" class="empty">No payroll data for this week.</td></tr>`;const sum=k=>rows.reduce((a,r)=>a+r[k],0);$('grossTotal').textContent=money(sum('gross'));$('allowanceTotal').textContent=money(sum('allowance'));$('labourTotal').textContent=money(sum('total'))}
function renderDashboard(){const rows=payrollRows(currentWeek);$('statEmployees').textContent=state.employees.length;$('statOutlets').textContent=state.locations.length;$('statHours').textContent=rows.reduce((a,r)=>a+r.weekday+r.sat+r.sun+r.ph,0).toFixed(1);$('statPayroll').textContent=money(rows.reduce((a,r)=>a+r.total,0));$('outletSummary').innerHTML=state.locations.map(loc=>{const rr=payrollRows(currentWeek,loc),h=rr.reduce((a,r)=>a+r.weekday+r.sat+r.sun+r.ph,0),c=rr.reduce((a,r)=>a+r.total,0);const d=storeDetail(loc),today=dateKey(new Date()),oh=storeHoursFor(loc,today);return`<div class="summary-item"><span>${esc(loc)}</span><strong>${h.toFixed(1)} hrs · ${money(c)}</strong>${oh?`<small>Today: ${formatTime(oh[0])}–${formatTime(oh[1])}</small>`:''}</div>`}).join('')}
function renderStores(){
  $('storesVerified').textContent=`Online details verified ${STORE_DETAILS_VERIFIED}`;
  $('storesGrid').innerHTML=state.locations.map(name=>{const d=storeDetail(name);if(!d)return`<article class="store-card"><h3>${esc(name)}</h3><p class="muted">No online details saved.</p></article>`;return`<article class="store-card"><div class="store-card-head"><div><div class="eyebrow">OUTLET</div><h3>${esc(d.displayName)}</h3></div><a class="source-link" href="${d.source}" target="_blank" rel="noopener">Official page ↗</a></div><p><strong>Address:</strong> ${esc(d.address)}</p><p><strong>Phone:</strong> <a href="tel:${d.phone.replace(/\s/g,'')}">${esc(d.phone)}</a></p><p><strong>Email:</strong> <a href="mailto:${esc(d.email)}">${esc(d.email)}</a></p><div class="hours-list">${DAY_NAMES.map((day,i)=>`<div><span>${day}</span><strong>${formatTime(d.hours[i][0])} – ${formatTime(d.hours[i][1])}</strong></div>`).join('')}</div></article>`}).join('')
}
function openShift(s=null){$('shiftForm').reset();$('shiftId').value=s?.id||'';$('shiftDialogTitle').textContent=s?'Edit shift':'Add shift';$('shiftEmployee').value=s?.employee||state.employees[0]?.name;$('shiftOutlet').value=s?.location||state.locations[0];$('shiftDate').value=s?effectiveShiftDate(s):dateKey(currentWeek);$('shiftType').value=s?.shiftType||'Custom';$('shiftStart').value=s?.start||'09:00';$('shiftEnd').value=s?.end||'17:00';$('shiftBreak').value=0;$('shiftPublicHoliday').checked=!!s?.publicHoliday;$('shiftNotes').value=s?.notes||'';updateStoreHoursHint();$('shiftDialog').showModal()}
window.editShift=id=>openShift(state.shifts.find(s=>s.id===id));window.deleteShift=async id=>{if(confirm('Delete this shift?')){state.shifts=state.shifts.filter(s=>s.id!==id);await save()}}
function openEmployee(e=null){$('employeeForm').reset();$('employeeDialogTitle').textContent=e?'Edit employee':'Add employee';$('employeeOriginalName').value=e?.name||'';$('employeeName').value=e?.name||'';$('employeeOutlet').value=e?.homeOutlet||state.locations[0];$('employeeType').value=e?.employmentType||'Casual';$('employeeRate').value=e?.baseRate??30;$('employeeSat').value=1;$('employeeSun').value=1;$('employeeAllowance').value=e?.weeklyAllowance??0;$('employeeDialog').showModal()}
