function csvDownload(filename,rows){const csv=rows.map(r=>r.map(v=>`"${String(v??'').replaceAll('"','""')}"`).join(',')).join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download=filename;a.click();URL.revokeObjectURL(a.href)}

function parseDateLoose(value){if(!value)return'';const d=new Date(value);if(!isNaN(d))return dateKey(d);const m=String(value).match(/([A-Za-z]{3})\s+(\d{1,2}),\s*(\d{4})/);if(m){const d2=new Date(`${m[1]} ${m[2]}, ${m[3]}`);if(!isNaN(d2))return dateKey(d2)}return''}
function accountSuppliers(){return [...new Set((state.accounts||[]).map(x=>x.supplier).filter(Boolean))].sort((a,b)=>a.localeCompare(b))}
function accountOutlets(){return [...new Set((state.accounts||[]).map(x=>x.outlet).filter(Boolean))].sort((a,b)=>a.localeCompare(b))}
function isOutstanding(a){return !['Paid','Prepaid','Credit received','Internal transfer','No payment required'].includes(a.paymentStatus)}
function filteredAccounts(){const outlet=$('accountsOutletFilter')?.value||'All outlets',supplier=$('accountsSupplierFilter')?.value||'All suppliers',status=$('accountsStatusFilter')?.value||'All statuses',dateSort=$('accountsDateSort')?.value||'newest',q=($('accountsSearch')?.value||'').trim().toLowerCase();const rows=(state.accounts||[]).filter(a=>(outlet==='All outlets'||a.outlet===outlet)&&(supplier==='All suppliers'||a.supplier===supplier)&&(status==='All statuses'||a.paymentStatus===status)&&(!q||`${a.invoiceNumber} ${a.supplier} ${a.outlet}`.toLowerCase().includes(q)));const time=a=>{const d=parseDateLoose(a.receivedDate||a.createdDate||'');return d?new Date(`${d}T00:00:00`).getTime():0};return rows.sort((a,b)=>{const diff=dateSort==='oldest'?time(a)-time(b):time(b)-time(a);if(diff!==0)return diff;return String(a.invoiceNumber||'').localeCompare(String(b.invoiceNumber||''),undefined,{numeric:true,sensitivity:'base'})})}
function updateAccountSelectionUI(){const rows=filteredAccounts(),ids=rows.map(a=>a.id),n=ids.filter(id=>selectedAccountIds.has(id)).length;if($('accountsSelectedCount'))$('accountsSelectedCount').textContent=selectedAccountIds.size;if($('selectAllAccounts')){$('selectAllAccounts').checked=ids.length>0&&n===ids.length;$('selectAllAccounts').indeterminate=n>0&&n<ids.length}}
function toggleAccountSelection(id,checked){checked?selectedAccountIds.add(id):selectedAccountIds.delete(id);updateAccountSelectionUI()}
function clearAccountSelection(){selectedAccountIds.clear();document.querySelectorAll('.account-select').forEach(x=>x.checked=false);updateAccountSelectionUI()}
function renderAccounts(){if(!$('accountsBody'))return;const oldO=$('accountsOutletFilter').value,oldS=$('accountsSupplierFilter').value;$('accountsOutletFilter').innerHTML=['All outlets',...accountOutlets()].map(x=>`<option>${esc(x)}</option>`).join('');$('accountsSupplierFilter').innerHTML=['All suppliers',...accountSuppliers()].map(x=>`<option>${esc(x)}</option>`).join('');if([...$('accountsOutletFilter').options].some(o=>o.value===oldO))$('accountsOutletFilter').value=oldO;if([...$('accountsSupplierFilter').options].some(o=>o.value===oldS))$('accountsSupplierFilter').value=oldS;$('supplierList').innerHTML=accountSuppliers().map(x=>`<option value="${esc(x)}">`).join('');$('outletList').innerHTML=accountOutlets().map(x=>`<option value="${esc(x)}">`).join('');const rows=filteredAccounts();$('accountsBody').innerHTML=rows.length?rows.map(a=>`<tr class="${a.paymentStatus==='Paid'?'paid-row':''}"><td><input class="account-select" type="checkbox" ${selectedAccountIds.has(a.id)?'checked':''} onchange="toggleAccountSelection('${a.id}',this.checked)"></td><td><strong>${esc(a.invoiceNumber||'')}</strong></td><td>${esc(a.supplier||'')}</td><td>${esc(a.outlet||'')}</td><td>${esc(a.receivedDate||'—')}</td><td>${esc(a.dueDate||'—')}</td><td>${Number(a.quantity||0)}</td><td>${money(a.amount)}</td><td><select class="inline-payment-status" onchange="quickUpdatePayment('${a.id}',this.value)">${['Unconfirmed','Unpaid','Due','Scheduled','Part paid','Prepaid','Paid','Disputed','Credit received','Internal transfer','No payment required'].map(x=>`<option ${x===(a.paymentStatus||'Unconfirmed')?'selected':''}>${x}</option>`).join('')}</select></td><td><input class="inline-paid-date" type="date" value="${esc(parseDateLoose(a.paidDate||''))}" onchange="quickUpdatePaidDate('${a.id}',this.value)"></td><td>${esc(a.receiptNumber||a.paymentReference||'—')}</td><td><div class="row-actions"><button class="link-btn" onclick="editInvoice('${a.id}')">Edit</button><button class="link-btn danger-text" onclick="deleteInvoice('${a.id}')">Delete</button></div></td></tr>`).join(''):'<tr><td colspan="12" class="empty">No invoices match these filters.</td></tr>';$('accountsFilteredCount').textContent=`(${rows.length} invoice${rows.length===1?'':'s'})`;$('accountsFilteredQty').textContent=rows.reduce((v,a)=>v+Number(a.quantity||0),0).toLocaleString();$('accountsFilteredTotal').textContent=money(rows.reduce((v,a)=>v+Number(a.amount||0),0));const all=state.accounts||[],today=dateKey(new Date()),soon=dateKey(addDays(new Date(),7));$('accOutstanding').textContent=money(all.filter(isOutstanding).reduce((v,a)=>v+Number(a.amount||0),0));$('accOverdue').textContent=all.filter(a=>isOutstanding(a)&&a.dueDate&&parseDateLoose(a.dueDate)<today).length;$('accDueSoon').textContent=all.filter(a=>isOutstanding(a)&&a.dueDate&&parseDateLoose(a.dueDate)>=today&&parseDateLoose(a.dueDate)<=soon).length;$('accPaid').textContent=money(all.filter(a=>a.paymentStatus==='Paid').reduce((v,a)=>v+Number(a.amount||0),0));updateAccountSelectionUI()}
async function quickUpdatePayment(id,status){const a=(state.accounts||[]).find(x=>x.id===id);if(!a)return;a.paymentStatus=status;if(status==='Paid'&&!a.paidDate)a.paidDate=dateKey(new Date());if(['Unconfirmed','Unpaid','Due','Scheduled','Disputed'].includes(status))a.paidDate='';if(await save())toast('Payment status updated')}
async function quickUpdatePaidDate(id,value){const a=(state.accounts||[]).find(x=>x.id===id);if(!a)return;a.paidDate=value;if(value)a.paymentStatus='Paid';if(await save())toast('Paid date updated')}
