$('weeklyRosterForm').onsubmit=async e=>{e.preventDefault();const outlet=$('weeklyRosterOutlet').value,employeeNames=new Set(state.employees.map(x=>x.name));state.shifts=state.shifts.filter(s=>!(s.location===outlet&&inWeek(s,currentWeek)&&employeeNames.has(s.employee)));document.querySelectorAll('#weeklyRosterBody .weekly-cell').forEach(cell=>{const preset=cell.querySelector('.weekly-preset').value;if(preset==='Off')return;const day=Number(cell.dataset.day),date=dateKey(addDays(currentWeek,day)),row={id:crypto.randomUUID(),employee:cell.dataset.employee,location:outlet,date,shiftType:preset,start:cell.querySelector('.weekly-start').value,end:cell.querySelector('.weekly-end').value,breakMinutes:0,publicHoliday:false,notes:'Created in weekly roster'};state.shifts.push(row)});$('weeklyRosterDialog').close();await save();toast('Weekly roster saved')};
$('statementForm').onsubmit=async e=>{e.preventDefault();const supplier=$('statementSupplier').value.trim(),outlet=$('statementOutlet').value.trim();if(!supplier||!outlet){toast('Choose supplier and outlet');return}const status=$('statementNewStatus').value,statementDate=$('statementDate').value;const rows=reconcileStatementRows();let added=0;for(const r of rows){const check=document.querySelector(`.statement-add-check[data-id="${r.id}"]`);if(r.result!=='Missing'||!check?.checked)continue;const row=applySupplierPaymentDefaults({id:crypto.randomUUID(),invoiceNumber:r.invoiceNumber,supplier,outlet,receivedDate:r.invoiceDate||statementDate,dueDate:r.dueDate||'',quantity:0,amount:Number(r.amount||0),receivingStatus:'Statement only',paymentStatus:status,paidDate:status==='Paid'?(statementDate||dateKey(new Date())):'',paymentReference:'',receiptNumber:'',notes:`Added from supplier statement ${statementImportFileName}`,source:'Supplier statement',sourceFile:statementImportFileName,statementDate});state.accounts.push(row);added++}if(!added){toast('No missing invoices selected');return}if(await save()){ $('statementDialog').close();renderAccounts();toast(`${added} missing invoice${added===1?'':'s'} added`)}};
$('invoiceForm').onsubmit=async e=>{e.preventDefault();const id=$('invoiceId').value||crypto.randomUUID();const row=applySupplierPaymentDefaults({id,invoiceNumber:$('invoiceNumber').value.trim(),supplier:$('invoiceSupplier').value.trim(),outlet:$('invoiceOutlet').value.trim(),receivedDate:$('invoiceReceivedDate').value,dueDate:$('invoiceDueDate').value,quantity:Number($('invoiceQuantity').value||0),amount:Number($('invoiceAmount').value||0),receivingStatus:'Received',paymentStatus:$('invoicePaymentStatus').value,paidDate:$('invoicePaidDate').value,paymentReference:$('invoicePaymentReference').value.trim(),receiptNumber:$('invoiceReceiptNumber').value.trim(),notes:$('invoiceNotes').value.trim(),source:$('invoiceSourceFile').value?'Supplier PDF':'Manual / corrected',sourceFile:$('invoiceSourceFile').value});const i=(state.accounts||[]).findIndex(a=>a.id===id);if(i>=0)state.accounts[i]=row;else state.accounts.push(row);$('invoiceDialog').close();if(await save())toast('Invoice saved')};
$('employeeForm').onsubmit=async e=>{e.preventDefault();const original=$('employeeOriginalName').value,name=$('employeeName').value.trim();if(!name)return;const row={name,homeOutlet:$('employeeOutlet').value,employmentType:$('employeeType').value,baseRate:Number($('employeeRate').value||0),satMultiplier:1,sunMultiplier:1,weeklyAllowance:Number($('employeeAllowance').value||0)};const i=state.employees.findIndex(x=>x.name===original);if(i>=0){state.employees[i]=row;if(original!==name)state.shifts.forEach(s=>{if(s.employee===original)s.employee=name})}else state.employees.push(row);$('employeeDialog').close();await save()};
$('copyWeekBtn').onclick=async()=>{const sourceStart=addDays(currentWeek,-7),source=state.shifts.filter(s=>inWeek(s.date,sourceStart));if(!source.length)return toast('Previous week has no shifts');source.forEach(s=>state.shifts.push({...s,id:crypto.randomUUID(),date:dateKey(addDays(new Date(effectiveShiftDate(s)+'T00:00:00'),7)),dateVersion:2}));await save();toast('Previous week copied')};
$('exportRosterBtn').onclick=()=>{const rows=[['Date','Employee','Outlet','Start','Finish','Paid hours','Public holiday'],...state.shifts.filter(s=>inWeek(s.date,currentWeek)).map(s=>[s.date,s.employee,s.location,s.start,s.end,hours(s).toFixed(2),s.publicHoliday?'Yes':'No'])];csvDownload(`supps247-roster-${dateKey(currentWeek)}.csv`,rows)};
$('exportPayrollBtn').onclick=()=>{const rows=payrollRows(payWeek,$('payrollOutletFilter').value||'All outlets');csvDownload(`supps247-payroll-${dateKey(payWeek)}.csv`,[['Employee','Weekday hours','Saturday hours','Sunday hours','Base rate','Gross','Allowance','Total labour cost'],...rows.map(r=>[r.emp.name,r.weekday.toFixed(2),r.sat.toFixed(2),r.sun.toFixed(2),r.emp.baseRate,r.gross.toFixed(2),r.allowance.toFixed(2),r.total.toFixed(2)])])};
(async()=>{const {data:{session}}=await db.auth.getSession();if(session)showApp(session);else setStatus(false,'Sign in required')})();


// Reports module
function reportGroups(field){
  const map=new Map();
  for(const row of state.accounts||[]){
    const key=String(row[field]||'Unknown').trim()||'Unknown';
    if(!map.has(key))map.set(key,{name:key,count:0,total:0,outstanding:0});
    const g=map.get(key);g.count++;g.total+=Number(row.amount||0);if(isOutstanding(row))g.outstanding+=Number(row.amount||0);
  }
  return [...map.values()].sort((a,b)=>b.total-a.total);
}
function renderReports(){
  if(!$('supplierReportBody'))return;
  const accounts=state.accounts||[];
  const labour=payrollRows(currentWeek).reduce((sum,row)=>sum+Number(row.total||0),0);
  $('reportSupplierSpend').textContent=money(accounts.reduce((sum,row)=>sum+Number(row.amount||0),0));
  $('reportOutstanding').textContent=money(accounts.filter(isOutstanding).reduce((sum,row)=>sum+Number(row.amount||0),0));
  const today=dateKey(new Date());
  $('reportOverdueCount').textContent=accounts.filter(row=>isOutstanding(row)&&row.dueDate&&parseDateLoose(row.dueDate)<today).length;
  $('reportLabour').textContent=money(labour);
  const supplierRows=reportGroups('supplier');
  const outletRows=reportGroups('outlet');
  $('supplierReportBody').innerHTML=supplierRows.length?supplierRows.map(r=>`<tr><td><strong>${esc(r.name)}</strong></td><td>${r.count}</td><td>${money(r.total)}</td><td>${money(r.outstanding)}</td></tr>`).join(''):'<tr><td colspan="4" class="empty">No account data.</td></tr>';
  $('outletReportBody').innerHTML=outletRows.length?outletRows.map(r=>`<tr><td><strong>${esc(r.name)}</strong></td><td>${r.count}</td><td>${money(r.total)}</td><td>${money(r.outstanding)}</td></tr>`).join(''):'<tr><td colspan="4" class="empty">No account data.</td></tr>';
  const attention=accounts.filter(row=>isOutstanding(row)).sort((a,b)=>(parseDateLoose(a.dueDate)||'9999').localeCompare(parseDateLoose(b.dueDate)||'9999')).slice(0,100);
  $('attentionReportBody').innerHTML=attention.length?attention.map(a=>`<tr><td><strong>${esc(a.invoiceNumber||'')}</strong></td><td>${esc(a.supplier||'')}</td><td>${esc(a.outlet||'')}</td><td>${esc(a.dueDate||'—')}</td><td>${money(a.amount)}</td><td><span class="status-pill status-${String(a.paymentStatus||'unconfirmed').toLowerCase().replaceAll(' ','-')}">${esc(a.paymentStatus||'Unconfirmed')}</span></td></tr>`).join(''):'<tr><td colspan="6" class="empty">No invoices require attention.</td></tr>';
}
function exportGroupedReport(field,fileName){
  const rows=reportGroups(field);
  csvDownload(fileName,[[field==='supplier'?'Supplier':'Outlet','Invoice count','Total spend','Outstanding'],...rows.map(r=>[r.name,r.count,r.total.toFixed(2),r.outstanding.toFixed(2)])]);
}
window.addEventListener('DOMContentLoaded',()=>{
  const supplierBtn=$('exportSupplierReportBtn'),outletBtn=$('exportOutletReportBtn');
  if(supplierBtn)supplierBtn.onclick=()=>exportGroupedReport('supplier',`supps247-supplier-report-${dateKey(new Date())}.csv`);
  if(outletBtn)outletBtn.onclick=()=>exportGroupedReport('outlet',`supps247-outlet-report-${dateKey(new Date())}.csv`);
});
